CREATE FUNCTION public.validate_hotel_payment_settings() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.payment_cutoff_days<0 OR NEW.payment_cutoff_days>365 OR NEW.advance_deposit_pct<=0 OR NEW.advance_deposit_pct>100 OR jsonb_typeof(NEW.approval_checklist)<>'array' OR jsonb_array_length(NEW.approval_checklist)=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.approval_checklist) c WHERE NULLIF(trim(c->>'label'),'') IS NULL OR NULLIF(c->>'code','') IS NULL) THEN RAISE EXCEPTION 'Provide a valid payment cutoff, deposit percentage and nonempty checklist'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_hotel_payment_settings BEFORE INSERT OR UPDATE ON public.hotel_workflow_settings FOR EACH ROW EXECUTE FUNCTION public.validate_hotel_payment_settings();
CREATE POLICY hotel_workflow_customer_read ON public.hotel_workflow_settings FOR SELECT TO authenticated USING(public.current_customer_id(tenant_id) IS NOT NULL);
GRANT SELECT ON public.estimate_items TO authenticated;
CREATE POLICY hotel_estimate_items_customer ON public.estimate_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.estimates e WHERE e.id=estimate_id AND e.customer_id=public.current_customer_id(e.tenant_id)));
CREATE FUNCTION public.hotel_review_payment_validation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.verified_payment_id IS NOT NULL AND NEW.verified_payment_id IS DISTINCT FROM OLD.verified_payment_id AND NOT EXISTS(SELECT 1 FROM public.payments p WHERE p.id=NEW.verified_payment_id AND p.status='received' AND COALESCE(p.amount_refunded,0)=0 AND p.invoice_id IS NULL AND p.amount>0 AND p.tenant_id=NEW.tenant_id) THEN RAISE EXCEPTION 'Only an unallocated, received and non-refunded payment can be verified'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.hotel_review_payment_validation() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER hotel_review_payment_validation BEFORE UPDATE ON public.hotel_booking_reviews FOR EACH ROW EXECUTE FUNCTION public.hotel_review_payment_validation();
CREATE FUNCTION public.hotel_review_status_gate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.hotel_booking_reviews; BEGIN IF NEW.service_type NOT IN ('hotel_dog','hotel_cat') OR NEW.invoice_id IS NOT NULL THEN RETURN NEW; END IF; SELECT * INTO r FROM public.hotel_booking_reviews WHERE booking_id=NEW.id; IF NEW.status IN ('confirmed','approved','pending_payment') AND r.approved_at IS NULL THEN NEW.status:='requested'; NEW.payment_hold_expires_at:=NULL; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.hotel_review_status_gate() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER zz_hotel_review_status_gate BEFORE INSERT OR UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION public.hotel_review_status_gate();
CREATE FUNCTION public.hotel_invalidate_approval() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; BEGIN IF TG_TABLE_NAME='bookings' THEN bid:=NEW.id; ELSE bid:=COALESCE(NEW.booking_id,OLD.booking_id); END IF; UPDATE public.hotel_booking_reviews SET approved_at=NULL,approved_by=NULL,estimate_id=NULL WHERE booking_id=bid AND verified_payment_id IS NULL; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$;
REVOKE ALL ON FUNCTION public.hotel_invalidate_approval() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER hotel_invalidate_dates AFTER UPDATE OF start_at,end_at,service_type ON public.bookings FOR EACH ROW WHEN (OLD.start_at IS DISTINCT FROM NEW.start_at OR OLD.end_at IS DISTINCT FROM NEW.end_at OR OLD.service_type IS DISTINCT FROM NEW.service_type) EXECUTE FUNCTION public.hotel_invalidate_approval();
CREATE TRIGGER hotel_invalidate_details AFTER UPDATE OF accommodation_type,discount_pct ON public.hotel_booking_details FOR EACH ROW WHEN (OLD.accommodation_type IS DISTINCT FROM NEW.accommodation_type OR OLD.discount_pct IS DISTINCT FROM NEW.discount_pct) EXECUTE FUNCTION public.hotel_invalidate_approval();
CREATE TRIGGER hotel_invalidate_extras AFTER INSERT OR UPDATE OR DELETE ON public.hotel_booking_surcharges FOR EACH ROW EXECUTE FUNCTION public.hotel_invalidate_approval();
CREATE TRIGGER hotel_invalidate_pets AFTER INSERT OR UPDATE OR DELETE ON public.booking_pets FOR EACH ROW EXECUTE FUNCTION public.hotel_invalidate_approval();